import { Box, Link, Text } from "../../atoms";
import { ObolSolidDarkBgH } from "../../icons";

export interface FooterLinksProps {
  title: string;
  /** Optional: makes the section heading itself a (subtle) link. */
  link?: string;
  links: { title: string; link: string }[];
}

const defaultLinks: FooterLinksProps[] = [
  {
    title: "Docs",
    link: "https://docs.obol.org",
    links: [
      {
        title: "Intro to Obol",
        link: "https://docs.obol.org/docs/int/Overview",
      },
      { title: "Charon", link: "https://github.com/ObolNetwork/charon" },
      {
        title: "DV Launchpad",
        link: "https://docs.obol.org/docs/dvk/distributed_validator_launchpad",
      },
    ],
  },
  {
    title: "Community",
    links: [
      { title: "Discord", link: "https://discord.com/invite/n6ebKsX46w" },
      { title: "Twitter", link: "https://twitter.com/ObolNetwork" },
    ],
  },
  {
    title: "More",
    links: [
      { title: "Blog", link: "https://blog.obol.org" },
      { title: "Github", link: "https://github.com/ObolNetwork" },
    ],
  },
];

export const Footer: React.FC<{ links?: FooterLinksProps[] }> = ({
  links = defaultLinks,
}) => {
  const year = new Date().getFullYear();
  return (
    <Box
      css={{
        display: "flex",
        "@sm": {
          flexDirection: "column",
          gap: "$xl",
        },
      }}
    >
      <Box
        css={{
          display: "flex",
          flexDirection: "column",
          // Left-align the logo with the copyright line under it.
          alignItems: "flex-start",
          gap: "$xxs",
          flex: 1,
        }}
      >
        <ObolSolidDarkBgH />
        <Text variant="body" css={{ fontSize: "$3" }}>
          {`Copyright © ${year} DV Labs.`}
        </Text>
      </Box>
      <Box
        className="footer-obol"
        css={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          "@sm": {
            gridTemplateColumns: "repeat(2, 1fr)",
            gap: "$xl",
          },
          flex: 2,
        }}
      >
        {links.map((item, index) => (
          <Box
            key={`link-section-${index}`}
            css={{ display: "flex", flexDirection: "column", gap: "10px" }}
          >
            {item.link ? (
              <Link
                target="_blank"
                href={item.link}
                css={{
                  color: "$body",
                  fontSize: "$5",
                  fontWeight: "$bold",
                  textDecoration: "none",
                  "&:hover": {
                    color: "$textLight",
                    textDecoration: "underline",
                  },
                }}
              >
                {item.title}
              </Link>
            ) : (
              <Text
                variant="body"
                css={{ fontSize: "$5", fontWeight: "$bold" }}
              >
                {item.title}
              </Text>
            )}
            {item.links.map((link, idx) => (
              <Link
                key={`link-${idx}`}
                variant="docs"
                target="_blank"
                href={link.link}
                css={{ color: "$textLight", fontSize: "$4" }}
              >
                {link.title}
              </Link>
            ))}
          </Box>
        ))}
      </Box>
    </Box>
  );
};
